// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract RecipientReverts {
    receive() external payable {
        revert("I don't accept Ether");
    }
}

contract InvMutTest is Test {
    Phishable c;
    RecipientReverts recipient;

    function setUp() public {
        c = new Phishable(address(this));
        recipient = new RecipientReverts();
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(1 ether);
    }

    function testRegression_property() public {
        bool ok;
        try c.withdrawAll(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
